FUNCTION_BLOCK FB_MetalHydride_H2StorageThermalPressure
(*
 * =========================================================================================
 * CYBER-PHYSICAL AUTOMATION ARCHITECTURE FOR 90-MPa SOLID-STATE HYDROGEN STORAGE
 * Subsystem: Internal Finned Micro-Channel Heat Exchanger Circulation & Thermal Desorption
 * Domain: SAE J2601 / ISO 19880-1 High-Density Stationary Fueling Buffer Systems
 * Core Metallurgy: High-Pressure AB2 / BCC Interstitial Alloy (Ti-Cr-Mn System)
 * Target Dynamics: 90.0 MPa (900.0 bar) Regulated Plateau Buffer Delivery
 * Safety Integrity Level: SIL-3 Capable Architecture (IEC 61508 / IEC 61511)
 * =========================================================================================
 *)
VAR_INPUT
    bEnable                 : BOOL;     (* Master functional block run enable [True=Run, False=Standby] *)
    bEmergencyStopOk        : BOOL;     (* Redundant SIL-3 safety circuit healthy [True=Healthy, False=Safety Trip] *)
    bResetAlarms            : BOOL;     (* Operator manual fault acknowledgement & latch clear *)
    rP_Bed_ChA_bar          : REAL;     (* Hydride core pressure sensor Ch-A [bar] (Range: 0.0 .. 1100.0) *)
    rP_Bed_ChB_bar          : REAL;     (* Hydride core pressure sensor Ch-B [bar] (Range: 0.0 .. 1100.0) *)
    rP_Bed_ChC_bar          : REAL;     (* Hydride core pressure sensor Ch-C [bar] (Range: 0.0 .. 1100.0) *)
    rT_Bed_Core_degC        : REAL;     (* Multi-point embedded core thermocouple average [deg C] (-50.0 .. 180.0) *)
    rT_Bed_Skin_degC        : REAL;     (* Type IV composite overwrapped shell surface temp [deg C] (-40.0 .. 100.0) *)
    rT_HTF_Inlet_degC       : REAL;     (* Heat transfer fluid jacket supply temperature [deg C] (-20.0 .. 160.0) *)
    rT_HTF_Outlet_degC      : REAL;     (* Heat transfer fluid jacket return temperature [deg C] (-20.0 .. 160.0) *)
    rFlow_HTF_m3h           : REAL;     (* Thermal oil circulating volumetric flow rate [m3/h] (0.0 .. 45.0) *)
    rP_HTF_Loop_bar         : REAL;     (* Thermal circulation closed-loop hydraulic pressure [bar] (0.0 .. 16.0) *)
    rFlow_H2_Demand_kgh     : REAL;     (* Fueling dispenser mass flow demand [kg/h] (0.0 .. 360.0 kg/h = 6 kg/min) *)
    rP_Target_Setpt_bar     : REAL;     (* Regulated 90-MPa buffer target pressure [bar] (Nominal 900.0 bar) *)
    rHeater_MaxPower_kW     : REAL;     (* Maximum rating of primary electrical immersion heater bank [kW] *)
    rCycleTime_s            : REAL := 0.05; (* Deterministic task loop interval [s] (Nominal: 50 ms) *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Storage system at equilibrium within 90-MPa dispensing envelope *)
    bDesorptionActive       : BOOL;     (* Active thermal desorption heat injection mode active *)
    rCmd_HeaterDuty_kW      : REAL;     (* Modulated electric heater bank power command [kW] (0.0 .. MaxPower) *)
    rCmd_HTFPumpSpeed_Pct   : REAL;     (* Circulation pump variable frequency drive speed [%] (0.0 .. 100.0) *)
    rCmd_H2RegValve_Pct     : REAL;     (* 90-MPa electro-hydraulic buffer discharge throttle [%] (0.0 .. 100.0) *)
    bCmd_H2IsolationESD     : BOOL;     (* SIL-3 high-pressure automated isolation valve [True=Open, False=Closed] *)
    bCmd_InertPurgeValve    : BOOL;     (* Nitrogen emergency blanket/purge solenoid [True=Energized, False=Closed] *)
    rVoted_Pressure_bar     : REAL;     (* 2oo3 Triple Modular Redundancy validated core pressure [bar] *)
    rEst_BedSOC_Pct         : REAL;     (* Real-time calibrated hydride state of charge [%] (0.0 .. 100.0) *)
    rEst_PlateauPres_bar    : REAL;     (* Van 't Hoff theoretical equilibrium plateau pressure [bar] *)
    wHealthStatusWord       : WORD;     (* Diagnostic bitfield: B0:ChA, B1:ChB, B2:ChC, B3:TMR, B4:HiP, B5:LoT, B6:Loop, B7:Trip *)
    bSafetyTrip             : BOOL;     (* Latched critical safety shutdown interlock indicator *)
    iCurrentState           : INT;      (* Active operational state machine index (0..99) *)
    sStatusMessage          : STRING[80]; (* Active engineering telemetry description text *)
END_VAR

VAR
    (* Redundant 2oo3 TMR Sensor Processing Variables *)
    bChA_Valid              : BOOL;
    bChB_Valid              : BOOL;
    bChC_Valid              : BOOL;
    rDiff_AB                : REAL;
    rDiff_BC                : REAL;
    rDiff_CA                : REAL;
    rTMR_Tolerance_bar      : REAL := 22.5; (* Maximum permitted divergence between redundant channels [bar] (2.5%) *)
    iHealthySensorCount     : INT;
    tChA_DiscrepTimer       : TON;
    tChB_DiscrepTimer       : TON;
    tChC_DiscrepTimer       : TON;

    (* Van 't Hoff Desorption Thermodynamics & Enthalpy Parameters *)
    (* Alloy: Ti1.1CrMn0.9 (Hydride bed capacity 180 kg H2 at 90 MPa, Delta_H = 29.8 kJ/mol, Delta_S = 108.4 J/mol*K) *)
    rDeltaH_J_per_mol       : REAL := 29800.0;  (* Desorption enthalpy [J / mol H2] *)
    rDeltaS_J_per_molK      : REAL := 108.4;    (* Desorption entropy [J / (mol H2 * K)] *)
    rGasConstant_R          : REAL := 8.31446;  (* Universal gas constant [J / (mol * K)] *)
    rP0_Reference_bar       : REAL := 1.01325;  (* Standard atmospheric reference pressure [bar] *)
    rMolarMass_H2_kg_mol    : REAL := 0.002016; (* Molecular weight of H2 [kg / mol] *)
    rBed_MaxH2_Capacity_kg  : REAL := 180.0;    (* Nominal full load H2 inventory [kg] *)
    rAccum_H2_Discharged_kg : REAL := 0.0;      (* Integrator of mass discharged [kg] *)

    (* State-Space Model Predictive Observer (Discrete-time linearized around 90-MPa operating point) *)
    (* State Vector: x = [T_bed_K, P_bed_bar, SOC_fraction, T_htf_out_K]^T *)
    (* Discrete State Transition Matrix A_d (4x4) at dt = 0.05 s *)
    rA11 : REAL := 0.9984;  rA12 : REAL := -0.00018; rA13 : REAL := 0.0000;  rA14 : REAL := 0.0015;
    rA21 : REAL := 0.3120;  rA22 : REAL := 0.9840;   rA23 : REAL := 0.0150;  rA24 : REAL := 0.0000;
    rA31 : REAL := 0.0000;  rA32 : REAL := 0.0000;   rA33 : REAL := 1.0000;  rA34 : REAL := 0.0000;
    rA41 : REAL := 0.0048;  rA42 : REAL := 0.0000;   rA43 : REAL := 0.0000;  rA44 : REAL := 0.9915;

    (* Input Coupling Matrix B_d (4x3): u = [Q_heater (kW), V_pump (m3/h), Valve_pos (%)] *)
    rB11 : REAL := 0.00038; rB12 : REAL := 0.00115;  rB13 : REAL := 0.00000;
    rB21 : REAL := 0.00125; rB22 : REAL := 0.00510;  rB23 : REAL := -0.04800;
    rB31 : REAL := 0.00000; rB32 : REAL := 0.00000;  rB33 : REAL := -0.00002;
    rB41 : REAL := 0.00310; rB42 : REAL := -0.00092; rB43 : REAL := 0.00000;

    (* Disturbance Coupling Matrix E_d (4x2): d = [Demand_flow (kg/h), T_Inlet (K)] *)
    rE11 : REAL := -0.00088; rE12 : REAL := 0.00019;
    rE21 : REAL := -0.05600; rE22 : REAL := 0.00000;
    rE31 : REAL := -0.00001; rE32 : REAL := 0.00000;
    rE41 : REAL := 0.00000;  rE42 : REAL := 0.00380;

    (* Internal Observer State Estimates *)
    rx1_Tbed_K              : REAL := 293.15;
    rx2_Pbed_bar            : REAL := 50.0;
    rx3_SOC_frac            : REAL := 1.0;
    rx4_Thtf_out_K          : REAL := 293.15;

    (* Luenberger Innovation Feedback Gains L (4x2) for measurement vector y = [T_core, P_voted] *)
    rL11 : REAL := 0.048;   rL12 : REAL := 0.00025;
    rL21 : REAL := 0.015;   rL22 : REAL := 0.13800;
    rL31 : REAL := 0.000;   rL32 : REAL := 0.00012;
    rL41 : REAL := 0.092;   rL42 : REAL := 0.00000;

    (* Linear Quadratic Regulator / MPC Feedback Matrix K (3x4) and Integral Tracking *)
    rKx11 : REAL := 1.920;  rKx12 : REAL := 0.245;  rKx13 : REAL := -48.0; rKx14 : REAL := -0.480;
    rKx21 : REAL := 0.135;  rKx22 : REAL := 0.042;  rKx23 : REAL := -6.20; rKx24 : REAL := 0.025;
    rKx31 : REAL := -0.055; rKx32 : REAL := 0.880;  rKx33 : REAL := 14.50; rKx34 : REAL := 0.000;

    (* Closed-Loop Filter & Integrator Memory *)
    rPressErrorIntegral     : REAL := 0.0;
    rTempErrorIntegral      : REAL := 0.0;
    rFiltered_Pressure_bar  : REAL := 50.0;
    rFiltered_Flow_kgh      : REAL := 0.0;
    rPressDerivative_bars   : REAL := 0.0;
    rPrevVotedPress_bar     : REAL := 50.0;

    (* Operational State Sequencing & Verification Timers *)
    tPreflightTimer         : TON;
    tPreheatSoakTimer       : TON;
    tCoolingTimer           : TON;
    tTripHoldoffTimer       : TON;

    (* State Machine Constants *)
    STATE_COLD_STANDBY          : INT := 0;
    STATE_PREFLIGHT_DIAGNOSTICS : INT := 10;
    STATE_THERMAL_PRIMING       : INT := 20;
    STATE_PRESSURE_REGULATION   : INT := 30;
    STATE_HIGH_DEMAND_BOOST     : INT := 40;
    STATE_DEPLETION_RAMPDOWN    : INT := 50;
    STATE_CONTROLLED_COOLING    : INT := 90;
    STATE_SAFETY_TRIP_LATCHED   : INT := 99;

    (* Intermediate Numerical Calculation Registers *)
    rT_Core_K               : REAL;
    rT_HTF_In_K             : REAL;
    rExponent               : REAL;
    rPressError_bar         : REAL;
    rTempTarget_degC        : REAL;
    rTempError_K            : REAL;
    rDesorpHeatFlow_kW      : REAL;
    rUnclampedHeater_kW     : REAL;
    rUnclampedPump_Pct      : REAL;
    rUnclampedValve_Pct     : REAL;
    rP_Median               : REAL;
    rResidual_P             : REAL;
    rResidual_T             : REAL;
    rDelta_x1               : REAL;
    rDelta_x2               : REAL;
    rDelta_x3               : REAL;
    rDelta_x4               : REAL;
END_VAR

(* ========================================================================================= *)
(* 1. SIL-3 FAIL-SAFE SUPERVISORY & HARDWARE SAFETY INTERLOCK CHECK                          *)
(* ========================================================================================= *)
IF NOT bEmergencyStopOk THEN
    bSafetyTrip             := TRUE;
    bSystemReady            := FALSE;
    bDesorptionActive       := FALSE;
    rCmd_HeaterDuty_kW      := 0.0;
    rCmd_HTFPumpSpeed_Pct   := 0.0;
    rCmd_H2RegValve_Pct     := 0.0;
    bCmd_H2IsolationESD     := FALSE; (* De-energize to close SIL-3 ESD valve *)
    bCmd_InertPurgeValve    := TRUE;  (* Open nitrogen barrier blanket *)
    iCurrentState           := STATE_SAFETY_TRIP_LATCHED;
    sStatusMessage          := 'EMERGENCY STOP TRIPPED: HARDWARE SAFETY RELAY OPEN';
    wHealthStatusWord       := wHealthStatusWord OR 16#0080;
    RETURN;
END_IF;

(* ========================================================================================= *)
(* 2. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) VOTING & FAULT DETECTION                          *)
(* ========================================================================================= *)
(* Validate individual sensor electrical ranges [0.0 to 1100.0 bar] *)
bChA_Valid := (rP_Bed_ChA_bar >= 0.0) AND (rP_Bed_ChA_bar <= 1100.0);
bChB_Valid := (rP_Bed_ChB_bar >= 0.0) AND (rP_Bed_ChB_bar <= 1100.0);
bChC_Valid := (rP_Bed_ChC_bar >= 0.0) AND (rP_Bed_ChC_bar <= 1100.0);

(* Compute channel differential magnitudes *)
rDiff_AB := ABS(rP_Bed_ChA_bar - rP_Bed_ChB_bar);
rDiff_BC := ABS(rP_Bed_ChB_bar - rP_Bed_ChC_bar);
rDiff_CA := ABS(rP_Bed_ChC_bar - rP_Bed_ChA_bar);

(* Classical 3-channel median voter logic *)
IF (rP_Bed_ChA_bar >= rP_Bed_ChB_bar AND rP_Bed_ChA_bar <= rP_Bed_ChC_bar) OR 
   (rP_Bed_ChA_bar <= rP_Bed_ChB_bar AND rP_Bed_ChA_bar >= rP_Bed_ChC_bar) THEN
    rP_Median := rP_Bed_ChA_bar;
ELSIF (rP_Bed_ChB_bar >= rP_Bed_ChA_bar AND rP_Bed_ChB_bar <= rP_Bed_ChC_bar) OR 
      (rP_Bed_ChB_bar <= rP_Bed_ChA_bar AND rP_Bed_ChB_bar >= rP_Bed_ChC_bar) THEN
    rP_Median := rP_Bed_ChB_bar;
ELSE
    rP_Median := rP_Bed_ChC_bar;
END_IF;

(* Channel divergence qualification timers to prevent nuisance tripping on spikes *)
tChA_DiscrepTimer(IN := (ABS(rP_Bed_ChA_bar - rP_Median) > rTMR_Tolerance_bar) OR NOT bChA_Valid, PT := T#500MS);
tChB_DiscrepTimer(IN := (ABS(rP_Bed_ChB_bar - rP_Median) > rTMR_Tolerance_bar) OR NOT bChB_Valid, PT := T#500MS);
tChC_DiscrepTimer(IN := (ABS(rP_Bed_ChC_bar - rP_Median) > rTMR_Tolerance_bar) OR NOT bChC_Valid, PT := T#500MS);

(* Update health word bits for transmitter channels *)
IF tChA_DiscrepTimer.Q THEN
    wHealthStatusWord := wHealthStatusWord OR 16#0001;
ELSE
    wHealthStatusWord := wHealthStatusWord AND NOT 16#0001;
END_IF;

IF tChB_DiscrepTimer.Q THEN
    wHealthStatusWord := wHealthStatusWord OR 16#0002;
ELSE
    wHealthStatusWord := wHealthStatusWord AND NOT 16#0002;
END_IF;

IF tChC_DiscrepTimer.Q THEN
    wHealthStatusWord := wHealthStatusWord OR 16#0004;
ELSE
    wHealthStatusWord := wHealthStatusWord AND NOT 16#0004;
END_IF;

(* Count active valid channels and execute degraded fallback *)
iHealthySensorCount := 3;
IF tChA_DiscrepTimer.Q THEN iHealthySensorCount := iHealthySensorCount - 1; END_IF;
IF tChB_DiscrepTimer.Q THEN iHealthySensorCount := iHealthySensorCount - 1; END_IF;
IF tChC_DiscrepTimer.Q THEN iHealthySensorCount := iHealthySensorCount - 1; END_IF;

IF iHealthySensorCount = 3 THEN
    rVoted_Pressure_bar := rP_Median;
    wHealthStatusWord   := wHealthStatusWord AND NOT 16#0008; (* Clear TMR degraded bit *)
ELSIF iHealthySensorCount = 2 THEN
    wHealthStatusWord   := wHealthStatusWord OR 16#0008;  (* Set TMR degraded bit (1oo2 fallback) *)
    IF tChA_DiscrepTimer.Q THEN
        rVoted_Pressure_bar := (rP_Bed_ChB_bar + rP_Bed_ChC_bar) * 0.5;
    ELSIF tChB_DiscrepTimer.Q THEN
        rVoted_Pressure_bar := (rP_Bed_ChA_bar + rP_Bed_ChC_bar) * 0.5;
    ELSE
        rVoted_Pressure_bar := (rP_Bed_ChA_bar + rP_Bed_ChB_bar) * 0.5;
    END_IF;
ELSIF iHealthySensorCount = 1 THEN
    wHealthStatusWord   := wHealthStatusWord OR 16#0008;
    IF NOT tChA_DiscrepTimer.Q THEN
        rVoted_Pressure_bar := rP_Bed_ChA_bar;
    ELSIF NOT tChB_DiscrepTimer.Q THEN
        rVoted_Pressure_bar := rP_Bed_ChB_bar;
    ELSE
        rVoted_Pressure_bar := rP_Bed_ChC_bar;
    END_IF;
ELSE
    (* Critical double sensor failure: Initiate immediate failsafe trip *)
    bSafetyTrip         := TRUE;
    iCurrentState       := STATE_SAFETY_TRIP_LATCHED;
    sStatusMessage      := 'CRITICAL TMR SENSOR FAULT: MULTIPLE TRANSMITTER DEVIATION';
    wHealthStatusWord   := wHealthStatusWord OR 16#0088;
    RETURN;
END_IF;

(* Dynamic pressure rate-of-change and low-pass filtering *)
rPressDerivative_bars := (rVoted_Pressure_bar - rPrevVotedPress_bar) / rCycleTime_s;
rPrevVotedPress_bar   := rVoted_Pressure_bar;
rFiltered_Pressure_bar := rFiltered_Pressure_bar + 0.18 * (rVoted_Pressure_bar - rFiltered_Pressure_bar);
rFiltered_Flow_kgh     := rFiltered_Flow_kgh + 0.25 * (rFlow_H2_Demand_kgh - rFiltered_Flow_kgh);

(* ========================================================================================= *)
(* 3. VAN 'T HOFF EQUILIBRIUM MODEL & STATE OF CHARGE INTEGRATION                            *)
(* ========================================================================================= *)
rT_Core_K := rT_Bed_Core_degC + 273.15;
IF rT_Core_K < 220.0 THEN rT_Core_K := 220.0; END_IF;

(* Van 't Hoff equation for interstitial metal hydride plateau pressure:
   ln(Peq / P0) = (Delta_H / (R * T)) - (Delta_S / R)
   Peq = P0 * exp((Delta_H / (R * T)) - (Delta_S / R))
*)
rExponent := (rDeltaH_J_per_mol / (rGasConstant_R * rT_Core_K)) - (rDeltaS_J_per_molK / rGasConstant_R);
IF rExponent > 12.0 THEN rExponent := 12.0; ELSIF rExponent < -2.0 THEN rExponent := -2.0; END_IF;
rEst_PlateauPres_bar := rP0_Reference_bar * EXP(rExponent);

(* Numerical Coulometric State of Charge (SOC) Integration *)
rAccum_H2_Discharged_kg := rAccum_H2_Discharged_kg + (rFlow_H2_Demand_kgh * (rCycleTime_s / 3600.0));
IF rBed_MaxH2_Capacity_kg > 0.001 THEN
    rEst_BedSOC_Pct := ((rBed_MaxH2_Capacity_kg - rAccum_H2_Discharged_kg) / rBed_MaxH2_Capacity_kg) * 100.0;
END_IF;
IF rEst_BedSOC_Pct < 0.0 THEN rEst_BedSOC_Pct := 0.0; ELSIF rEst_BedSOC_Pct > 100.0 THEN rEst_BedSOC_Pct := 100.0; END_IF;

(* ========================================================================================= *)
(* 4. MULTIVARIABLE STATE-SPACE OBSERVER ESTIMATION                                         *)
(* ========================================================================================= *)
rT_HTF_In_K := rT_HTF_Inlet_degC + 273.15;

(* Compute innovation residuals *)
rResidual_T := rT_Core_K - rx1_Tbed_K;
rResidual_P := rVoted_Pressure_bar - rx2_Pbed_bar;

(* State vector update: x(k+1) = A_d*x(k) + B_d*u(k) + E_d*d(k) + L*(y - C*x) *)
rDelta_x1 := (rA11 * rx1_Tbed_K + rA12 * rx2_Pbed_bar + rA13 * rx3_SOC_frac + rA14 * rx4_Thtf_out_K)
           + (rB11 * rCmd_HeaterDuty_kW + rB12 * rFlow_HTF_m3h + rB13 * rCmd_H2RegValve_Pct)
           + (rE11 * rFiltered_Flow_kgh + rE12 * rT_HTF_In_K)
           + (rL11 * rResidual_T + rL12 * rResidual_P) - rx1_Tbed_K;

rDelta_x2 := (rA21 * rx1_Tbed_K + rA22 * rx2_Pbed_bar + rA23 * rx3_SOC_frac + rA24 * rx4_Thtf_out_K)
           + (rB21 * rCmd_HeaterDuty_kW + rB22 * rFlow_HTF_m3h + rB23 * rCmd_H2RegValve_Pct)
           + (rE21 * rFiltered_Flow_kgh + rE22 * rT_HTF_In_K)
           + (rL21 * rResidual_T + rL22 * rResidual_P) - rx2_Pbed_bar;

rDelta_x3 := (rA31 * rx1_Tbed_K + rA32 * rx2_Pbed_bar + rA33 * rx3_SOC_frac + rA34 * rx4_Thtf_out_K)
           + (rB31 * rCmd_HeaterDuty_kW + rB32 * rFlow_HTF_m3h + rB33 * rCmd_H2RegValve_Pct)
           + (rE31 * rFiltered_Flow_kgh + rE32 * rT_HTF_In_K)
           + (rL31 * rResidual_T + rL32 * rResidual_P) - rx3_SOC_frac;

rDelta_x4 := (rA41 * rx1_Tbed_K + rA42 * rx2_Pbed_bar + rA43 * rx3_SOC_frac + rA44 * rx4_Thtf_out_K)
           + (rB41 * rCmd_HeaterDuty_kW + rB42 * rFlow_HTF_m3h + rB43 * rCmd_H2RegValve_Pct)
           + (rE41 * rFiltered_Flow_kgh + rE42 * rT_HTF_In_K)
           + (rL41 * rResidual_T + rL42 * rResidual_P) - rx4_Thtf_out_K;

rx1_Tbed_K     := rx1_Tbed_K + rDelta_x1;
rx2_Pbed_bar   := rx2_Pbed_bar + rDelta_x2;
rx3_SOC_frac   := rx3_SOC_frac + rDelta_x3;
rx4_Thtf_out_K := rx4_Thtf_out_K + rDelta_x4;

(* Observer anti-divergence boundary enforcement *)
IF rx1_Tbed_K < 220.0 THEN rx1_Tbed_K := 220.0; ELSIF rx1_Tbed_K > 450.0 THEN rx1_Tbed_K := 450.0; END_IF;
IF rx2_Pbed_bar < 0.0 THEN rx2_Pbed_bar := 0.0; ELSIF rx2_Pbed_bar > 1100.0 THEN rx2_Pbed_bar := 1100.0; END_IF;

(* ========================================================================================= *)
(* 5. CRITICAL PROCESS SAFETY ENVELOPE INTERLOCKS                                            *)
(* ========================================================================================= *)
(* High-High Pressure Emergency Trip (105% of 90.0 MPa = 945.0 bar) *)
IF rVoted_Pressure_bar > 945.0 THEN
    bSafetyTrip       := TRUE;
    iCurrentState     := STATE_SAFETY_TRIP_LATCHED;
    sStatusMessage    := 'CRITICAL OVERPRESSURE TRIP: BED EXCEEDED 945 BAR (105% RATING)';
    wHealthStatusWord := wHealthStatusWord OR 16#0010;
END_IF;

(* Vessel Skin Over-Temperature Interlock (Composite envelope protection < 85 deg C) *)
IF rT_Bed_Skin_degC > 85.0 THEN
    bSafetyTrip       := TRUE;
    iCurrentState     := STATE_SAFETY_TRIP_LATCHED;
    sStatusMessage    := 'SKIN OVERTEMPERATURE TRIP: COMPOSITE LINER INTEGRITY PROTECTION';
    wHealthStatusWord := wHealthStatusWord OR 16#0020;
END_IF;

(* Thermal Fluid Cavitation / Loss of Flow Interlock *)
IF (iCurrentState >= STATE_THERMAL_PRIMING) AND (rP_HTF_Loop_bar < 1.5) THEN
    bSafetyTrip       := TRUE;
    iCurrentState     := STATE_SAFETY_TRIP_LATCHED;
    sStatusMessage    := 'HTF HYDRAULIC PRESSURE COLLAPSE: CAVITATION DETECTED';
    wHealthStatusWord := wHealthStatusWord OR 16#0040;
END_IF;

(* ========================================================================================= *)
(* 6. SEQUENTIAL MULTI-STAGE FINITE STATE MACHINE (CASE LOGIC)                              *)
(* ========================================================================================= *)
CASE iCurrentState OF

    STATE_COLD_STANDBY: (* State 0: Passive storage, valves locked closed *)
        bSystemReady            := FALSE;
        bDesorptionActive       := FALSE;
        rCmd_HeaterDuty_kW      := 0.0;
        rCmd_HTFPumpSpeed_Pct   := 0.0;
        rCmd_H2RegValve_Pct     := 0.0;
        bCmd_H2IsolationESD     := FALSE;
        bCmd_InertPurgeValve    := FALSE;
        rPressErrorIntegral     := 0.0;
        rTempErrorIntegral      := 0.0;
        sStatusMessage          := 'COLD STANDBY: AWAITING ENABLE AND PRESSURE DISPATCH';

        IF bEnable AND NOT bSafetyTrip THEN
            iCurrentState := STATE_PREFLIGHT_DIAGNOSTICS;
        END_IF;

    STATE_PREFLIGHT_DIAGNOSTICS: (* State 10: Automatic pre-run self-test *)
        bSystemReady            := FALSE;
        bDesorptionActive       := FALSE;
        rCmd_HeaterDuty_kW      := 0.0;
        rCmd_HTFPumpSpeed_Pct   := 0.0;
        rCmd_H2RegValve_Pct     := 0.0;
        bCmd_H2IsolationESD     := FALSE;
        bCmd_InertPurgeValve    := FALSE;
        sStatusMessage          := 'PREFLIGHT: VERIFYING TMR HEALTH AND HYDRAULIC ENVELOPE';

        tPreflightTimer(IN := TRUE, PT := T#2S);
        IF tPreflightTimer.Q THEN
            tPreflightTimer(IN := FALSE);
            IF (iHealthySensorCount >= 2) AND (rP_HTF_Loop_bar >= 2.0) AND (rT_Bed_Core_degC < 85.0) THEN
                iCurrentState := STATE_THERMAL_PRIMING;
            ELSE
                bSafetyTrip    := TRUE;
                iCurrentState  := STATE_SAFETY_TRIP_LATCHED;
                sStatusMessage := 'PREFLIGHT SELF-TEST FAILED: HYDRAULIC OR SENSOR LIMITS EXCEEDED';
            END_IF;
        END_IF;

    STATE_THERMAL_PRIMING: (* State 20: Gentle circulation start and bed thermal warm-up *)
        bSystemReady            := FALSE;
        bDesorptionActive       := TRUE;
        rCmd_HTFPumpSpeed_Pct   := 35.0; (* Establish base laminar-turbulent transition flow *)
        rCmd_HeaterDuty_kW      := rHeater_MaxPower_kW * 0.25; (* 25% soft-start heater power *)
        rCmd_H2RegValve_Pct     := 0.0;
        bCmd_H2IsolationESD     := FALSE;
        sStatusMessage          := 'THERMAL PRIMING: HEATING BED TO OPERATIONAL DISPATCH LEVEL';

        (* Check core temperature and vapor pressure ramp *)
        IF (rT_Bed_Core_degC >= 42.0) AND (rVoted_Pressure_bar >= 650.0) THEN
            tPreheatSoakTimer(IN := TRUE, PT := T#5S);
            IF tPreheatSoakTimer.Q THEN
                tPreheatSoakTimer(IN := FALSE);
                iCurrentState := STATE_PRESSURE_REGULATION;
            END_IF;
        ELSE
            tPreheatSoakTimer(IN := FALSE);
        END_IF;

        IF NOT bEnable THEN
            iCurrentState := STATE_CONTROLLED_COOLING;
        END_IF;

    STATE_PRESSURE_REGULATION: (* State 30: Active 90-MPa Buffer Dispatch Regulation *)
        bSystemReady        := (rVoted_Pressure_bar >= (rP_Target_Setpt_bar - 25.0)) AND 
                               (rVoted_Pressure_bar <= (rP_Target_Setpt_bar + 25.0));
        bDesorptionActive   := TRUE;
        bCmd_H2IsolationESD := TRUE; (* Open 90-MPa isolation ball valve *)
        sStatusMessage      := 'ACTIVE REGULATION: 90-MPa CLOSED-LOOP MPC DESORPTION CONTROL';

        (* Calculate control errors *)
        rPressError_bar  := rP_Target_Setpt_bar - rVoted_Pressure_bar;
        rTempTarget_degC := 55.0 + (rFiltered_Flow_kgh * 0.12); (* Target temperature scheduled against flow demand *)
        IF rTempTarget_degC > 92.0 THEN rTempTarget_degC := 92.0; END_IF;
        rTempError_K     := (rTempTarget_degC + 273.15) - rx1_Tbed_K;

        (* Anti-windup bounded error integration *)
        rPressErrorIntegral := rPressErrorIntegral + (rPressError_bar * rCycleTime_s);
        IF rPressErrorIntegral > 400.0 THEN rPressErrorIntegral := 400.0;
        ELSIF rPressErrorIntegral < -400.0 THEN rPressErrorIntegral := -400.0;
        END_IF;

        (* Endothermic Desorption Heat Demand: Q_rxn = (m_dot / M_H2) * Delta_H *)
        rDesorpHeatFlow_kW := (rFiltered_Flow_kgh / 3600.0) * (rDeltaH_J_per_mol / rMolarMass_H2_kg_mol) * 0.001;

        (* Multivariable MPC State Feedback Control Synthesis *)
        rUnclampedHeater_kW := (rKx11 * rTempError_K) + (rKx12 * rPressError_bar) 
                             + (rPressErrorIntegral * 0.045) + (rDesorpHeatFlow_kW * 1.05);

        rUnclampedPump_Pct  := 40.0 + (rKx21 * rTempError_K) + (rFiltered_Flow_kgh * 0.15);

        rUnclampedValve_Pct := 50.0 + (rKx32 * rPressError_bar) - (rPressDerivative_bars * 1.85);

        (* Actuator Saturation Clamping *)
        IF rUnclampedHeater_kW > rHeater_MaxPower_kW THEN
            rCmd_HeaterDuty_kW := rHeater_MaxPower_kW;
        ELSIF rUnclampedHeater_kW < 0.0 THEN
            rCmd_HeaterDuty_kW := 0.0;
        ELSE
            rCmd_HeaterDuty_kW := rUnclampedHeater_kW;
        END_IF;

        IF rUnclampedPump_Pct > 100.0 THEN
            rCmd_HTFPumpSpeed_Pct := 100.0;
        ELSIF rUnclampedPump_Pct < 25.0 THEN
            rCmd_HTFPumpSpeed_Pct := 25.0;
        ELSE
            rCmd_HTFPumpSpeed_Pct := rUnclampedPump_Pct;
        END_IF;

        IF rUnclampedValve_Pct > 100.0 THEN
            rCmd_H2RegValve_Pct := 100.0;
        ELSIF rUnclampedValve_Pct < 0.0 THEN
            rCmd_H2RegValve_Pct := 0.0;
        ELSE
            rCmd_H2RegValve_Pct := rUnclampedValve_Pct;
        END_IF;

        (* High-Demand Transient Detection *)
        IF (rFiltered_Flow_kgh > 120.0) OR (rPressDerivative_bars < -4.0) THEN
            iCurrentState := STATE_HIGH_DEMAND_BOOST;
        END_IF;

        (* Depletion Detection *)
        IF (rEst_BedSOC_Pct < 15.0) THEN
            iCurrentState := STATE_DEPLETION_RAMPDOWN;
        END_IF;

        IF NOT bEnable THEN
            iCurrentState := STATE_CONTROLLED_COOLING;
        END_IF;

    STATE_HIGH_DEMAND_BOOST: (* State 40: High dispenser discharge rate feedforward surge boost *)
        bSystemReady          := TRUE;
        bDesorptionActive     := TRUE;
        bCmd_H2IsolationESD   := TRUE;
        sStatusMessage        := 'BOOST MODE: HIGH FLOW DISPENSE TRANSIENT COMPENSATION ACTIVE';

        (* Maximize heat transfer rate to prevent localized bed refrigeration & phase lock *)
        rCmd_HTFPumpSpeed_Pct := 95.0;
        rCmd_HeaterDuty_kW    := rHeater_MaxPower_kW;
        rCmd_H2RegValve_Pct   := 75.0 + ((rP_Target_Setpt_bar - rVoted_Pressure_bar) * 0.8);
        IF rCmd_H2RegValve_Pct > 100.0 THEN rCmd_H2RegValve_Pct := 100.0; END_IF;

        (* Return to normal regulation when flow demand stabilizes *)
        IF (rFiltered_Flow_kgh <= 95.0) AND (rPressDerivative_bars > -1.5) THEN
            iCurrentState := STATE_PRESSURE_REGULATION;
        END_IF;

        IF NOT bEnable THEN
            iCurrentState := STATE_CONTROLLED_COOLING;
        END_IF;

    STATE_DEPLETION_RAMPDOWN: (* State 50: Bed approaching lower SOC limit; manage scavenge heat *)
        bSystemReady          := FALSE;
        bDesorptionActive     := TRUE;
        bCmd_H2IsolationESD   := TRUE;
        sStatusMessage        := 'DEPLETION SCAVENGE: LOW INVENTORY (SOC < 15%) CONTROLLED TAPERING';

        (* Moderate heater to avoid overheating empty alloy matrix *)
        rCmd_HeaterDuty_kW    := rHeater_MaxPower_kW * 0.40;
        rCmd_HTFPumpSpeed_Pct := 50.0;
        rCmd_H2RegValve_Pct   := 35.0;

        IF (rEst_BedSOC_Pct < 3.0) OR (rVoted_Pressure_bar < 450.0) OR NOT bEnable THEN
            iCurrentState := STATE_CONTROLLED_COOLING;
        END_IF;

    STATE_CONTROLLED_COOLING: (* State 90: Orderly thermal ramp-down and loop isolation *)
        bSystemReady          := FALSE;
        bDesorptionActive     := FALSE;
        rCmd_HeaterDuty_kW    := 0.0; (* Heater immediately de-energized *)
        rCmd_H2RegValve_Pct   := 0.0;
        bCmd_H2IsolationESD   := FALSE; (* Close delivery valve *)
        sStatusMessage        := 'CONTROLLED COOLING: CIRCULATING HTF TO DISSIPATE CORE RESIDUAL ENTHALPY';

        (* Continue pump circulation for 30 seconds to safely disperse residual heater block heat *)
        rCmd_HTFPumpSpeed_Pct := 40.0;
        tCoolingTimer(IN := TRUE, PT := T#30S);
        IF tCoolingTimer.Q THEN
            tCoolingTimer(IN := FALSE);
            rCmd_HTFPumpSpeed_Pct := 0.0;
            iCurrentState         := STATE_COLD_STANDBY;
        END_IF;

    STATE_SAFETY_TRIP_LATCHED: (* State 99: Latched safety emergency shutdown state *)
        bSystemReady            := FALSE;
        bDesorptionActive       := FALSE;
        rCmd_HeaterDuty_kW      := 0.0;
        rCmd_HTFPumpSpeed_Pct   := 0.0;
        rCmd_H2RegValve_Pct     := 0.0;
        bCmd_H2IsolationESD     := FALSE;
        bCmd_InertPurgeValve    := TRUE; (* Nitrogen blanket purge *)

        (* Require physical reset push-button and healthy safety circuit *)
        IF bResetAlarms AND bEmergencyStopOk AND (rVoted_Pressure_bar < 910.0) AND (rT_Bed_Skin_degC < 75.0) THEN
            bSafetyTrip          := FALSE;
            wHealthStatusWord    := 16#0000;
            bCmd_InertPurgeValve := FALSE;
            iCurrentState        := STATE_COLD_STANDBY;
            sStatusMessage       := 'SAFETY FAULT ACKNOWLEDGED: RESTORED TO COLD STANDBY';
        END_IF;

ELSE
    (* Fallback defensively to latched safety trip *)
    iCurrentState := STATE_SAFETY_TRIP_LATCHED;
END_CASE;

END_FUNCTION_BLOCK
